const catalogs = [
  ["en", "} as const;"],
  ["ja", "} satisfies Catalog;"],
  ["zh", "} satisfies Catalog;"],
  ["es", "} satisfies Catalog;"],
];

for (const [locale, footer] of catalogs) {
  const path = new URL(`../lib/locales/${locale}.ts`, import.meta.url);
  let source = await readFile(path, "utf8");
  const additions = [];
  const localeIndex = { en: 1, ja: 2, zh: 3, es: 4 }[locale];
  for (const row of rows) {
    const key = `${JSON.stringify(row[0])}:`;
    if (!source.includes(key)) additions.push(`  ${JSON.stringify(row[0])}: ${JSON.stringify(row[localeIndex])},`);
  }
  if (additions.length) {
    const marker = `\n${footer}`;
    if (!source.includes(marker)) throw new Error(`Missing catalog footer: ${locale}`);
    source = source.replace(marker, `\n${additions.join("\n")}\n${footer}`);
    await writeFile(path, source, "utf8");
  }
}

console.log(JSON.stringify({ rows: rows.length }));
